41\u0435 \u043d\u0443\u0436\u043d\u044b\u0435 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442** (numpy, pandas, scipy, sklearn, torch, xgboost, lightgbm, h5py \u2014 MISSING), \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430. \u0422\u043e \u0435\u0441\u0442\u044c \u0434\u0430\u0436\u0435 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u00abdry-run\u00bb \u0432\u043e\u0437\u043c\u043e\u0436\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0447\u0438\u0441\u0442\u043e\u043c Python \u043b\u0438\u0431\u043e \u043f\u043e\u0441\u043b\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u0438\u0437 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0445 wheels.\n- \u0421\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435, \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e \u043f\u0440\u044f\u043c\u043e: **\u043f\u0440\u043e\u043f\u0443\u0441\u043a\u0438, \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b, \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u044b \u0438 \u0441\u043e\u0441\u0442\u0430\u0432 \u0444\u0430\u0439\u043b\u043e\u0432 \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e**. \u041d\u0438\u0436\u0435 \u0432\u0441\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043e \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0435 \u2014 \u044d\u0442\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u0443\u0435\u043c\u043e\u0435 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 (\u043f\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u0437\u0430\u0434\u0430\u0447\u0438 + \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0430\u044f \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u0430 \u043f\u043e DrivAerNet++), \u0430 \u043d\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0444\u0430\u043a\u0442\u043e\u0432. \u042d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u00ab\u0432\u0441\u043b\u0435\u043f\u0443\u044e\u00bb, \u043f\u043e\u0434 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043d\u0443\u044e \u0441\u0445\u0435\u043c\u0443 \u0434\u0430\u043d\u043d\u044b\u0445; \u043d\u0438\u043a\u0430\u043a\u0438\u0445 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 \u043d\u0435 \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u043c.\n\n**\u041e\u043f\u0438\u0441\u0430\u043d\u0438\u0435 DrivAerNet++ (\u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b; \u043d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438, \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u043e \u26a0):**\n- 3 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u043a\u0443\u0437\u043e\u0432\u043e\u0432: fastback, notchback, estateback; \u26a0 \u043f\u043e ~5000 CFD-\u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0439 \u043d\u0430 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e, \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u043e ~15 000 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439.\n- \u041a\u0430\u0436\u0434\u0430\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044f \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u0435\u043a\u0442\u043e\u0440\u043e\u043c \u0438\u0437 26 \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u043e\u0432 (\u0433\u0435\u043e\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0434\u0435\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438 \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 DrivAer; \u043f\u043e \u26a0 \u2014 \u0432\u044b\u0431\u043e\u0440\u043a\u0430 \u0438\u0437 \u043b\u0430\u0442\u0438\u043d\u0441\u043a\u043e\u0433\u043e \u0433\u0438\u043f\u0435\u0440\u043a\u0443\u0431\u0430).\n- \u0426\u0435\u043b\u044c \u2014 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442 \u0430\u044d\u0440\u043e\u0434\u0438\u043d\u0430\u043c\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0441\u043e\u043f\u0440\u043e\u0442\u0438\u0432\u043b\u0435\u043d\u0438\u044f Cd \u0438\u0437 RANS-CFD (\u0441\u043a\u0430\u043b\u044f\u0440); \u0432 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u043e\u043c \u0440\u0435\u043b\u0438\u0437\u0435 \u043e\u043d \u043e\u0442\u0434\u0430\u0451\u0442\u0441\u044f \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u0435\u0439 (CSV). \u041f\u043e\u043b\u043d\u044b\u0439 \u0440\u0435\u043b\u0438\u0437 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043f\u043e\u0432\u0435\u0440\u0445\u043d\u043e\u0441\u0442\u0438 meshes \u0438 \u043f\u043e\u043b\u044f \u0442\u0435\u0447\u0435\u043d\u0438\u044f \u2014 \u0434\u043b\u044f \u0442\u0430\u0431\u043b\u0438\u0447\u043d\u043e\u0433\u043e surrogate-\u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u043d\u0435 \u043d\u0443\u0436\u043d\u044b.\n- \u0414\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b: \u043f\u0440\u0438 \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u043e\u0439 LHS-\u0432\u044b\u0431\u043e\u0440\u043a\u0435 \u0442\u043e\u0447\u043d\u044b\u0435 \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b \u043c\u0430\u043b\u043e\u0432\u0435\u0440\u043e\u044f\u0442\u043d\u044b, \u043d\u043e \u26a0 \u043f\u043e\u0447\u0442\u0438-\u0434\u0443\u0431\u043b\u0438\u0440\u0443\u044e\u0449\u0438\u0435\u0441\u044f \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b; \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430 \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0434\u0430\u043d\u043d\u044b\u0445.\n\n## 2) \u041f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u043c\u044b\u0439 \u043f\u043b\u0430\u043d \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 (\u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0439, \u0431\u0435\u0437 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438)\n\n**\u0414\u0430\u043d\u043d\u044b\u0435 \u0438 \u0446\u0435\u043b\u044c.** \u0422\u0430\u0431\u043b\u0438\u0447\u043d\u044b\u0439 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u043e\u043d\u043d\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442: X (26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 [+ \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0439/\u043e\u0434\u0438\u043d-hot \u043f\u0440\u0438\u0437\u043d\u0430\u043a \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u043a\u0443\u0437\u043e\u0432\u0430 \u2014 \u0441\u043c. \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f]) \u2192 y (Cd). \u041f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u043d\u0430 \u0432\u0445\u043e\u0434\u0435: (\u0430) \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0441\u0445\u0435\u043c\u044b, N, \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043e\u0432, \u0442\u043e\u0447\u043d\u044b\u0445 \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u043e\u0432; (\u0431) \u043f\u043e\u043f\u0430\u0440\u043d\u0430\u044f\u8fd1-duplicate \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u043e \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u044e \u0432 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u0441\u0442\u0440\u0430\u043d\u0441\u0442\u0432\u0435.\n\n**\u0421\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 (\u043e\u0442 \u0434\u0435\u0448\u0435\u0432\u043e\u0433\u043e \u043a \u0434\u043e\u0440\u043e\u0433\u043e\u043c\u0443):**\n1. \u041b\u0438\u043d\u0435\u0439\u043d\u044b\u0435/\u043f\u043e\u043b\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u044d\u0442\u0430\u043b\u043e\u043d\u044b: Ridge \u043d\u0430 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0430\u0445; Ridge \u043d\u0430 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0438\u0447\u043d\u043e\u043c \u0438 \u043a\u0443\u0431\u0438\u0447\u0435\u0441\u043a\u043e\u043c \u0431\u0430\u0437\u0438\u0441\u0435 (\u0441 \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u0438\u0437\u0430\u0446\u0438\u0435\u0439) \u2014 \u00ab\u043d\u0443\u043b\u0435\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c\u00bb \u043d\u0435\u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0441\u0442\u0438.\n2. \u0413\u0440\u0430\u0434\u0438\u0435\u043d\u0442\u043d\u044b\u0439 \u0431\u0443\u0441\u0442\u0438\u043d\u0433 (hist GBR / LightGBM-XGB, \u0435\u0441\u043b\u0438 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043c) \u0438 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043b\u0435\u0441.\n3. \u041f\u043e\u043b\u043d\u043e\u0441\u0432\u044f\u0437\u043d\u0430\u044f NN (MLP 2\u20133 \u0441\u043a\u0440\u044b\u0442\u044b\u0445 \u0441\u043b\u043e\u044f, \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0430\u0446\u0438\u044f \u0432\u0445\u043e\u0434\u043e\u0432, \u0440\u0430\u043d\u043d\u044f\u044f \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043d\u0430 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0435\u043c \u0432\u0430\u043b\u0438\u0434\u0435).\n4. \u0413\u0430\u0443\u0441\u0441\u043e\u0432\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u0446\u0435\u0441\u0441 (ARD-RBF/Matern) \u043a\u0430\u043a \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0441\u0442\u043d\u044b\u0439 \u044d\u0442\u0430\u043b\u043e\u043d; \u0438\u0437-\u0437\u0430 O(N\u00b3) \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u043e\u0439 (\u043a\u0430\u043f \u26a0 3\u20135k \u0442\u043e\u0447\u0435\u043a; \u0434\u043b\u044f \u0431\u043e\u043b\u044c\u0448\u0438\u0445 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432 \u043a\u0440\u0438\u0432\u043e\u0439 \u2014 sparse/\u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043e\u0447\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c \u0438\u043b\u0438 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043a\u0440\u0438\u0432\u043e\u0439 GP \u043d\u0430 \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435).\n5. \u0414\u0451\u0448\u0435\u0432\u043e: kNN \u0438 RBF-SVR \u043a\u0430\u043a \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0442\u043e\u0447\u043a\u0438 (\u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e, \u043f\u0440\u0438 \u0431\u044e\u0434\u0436\u0435\u0442\u0435).\n\n**\u0420\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u0435.** \u0415\u0434\u0438\u043d\u044b\u0439 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u044b\u0439 holdout: 70/15/15 train/val/test \u043d\u0430 \u0432\u0435\u0441\u044c \u043f\u0443\u043b (seed \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d, \u0442\u0435\u0441\u0442 \u0437\u0430\u043c\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0434\u043e \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u043e\u0446\u0435\u043d\u043a\u0438). \u0412\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u0438 \u0440\u0430\u043d\u043d\u0435\u0439 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 NN.\n\n**Learning curve \u0441 \u0432\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u043c\u0438 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430\u043c\u0438.** \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e seed r: \u043e\u0434\u043d\u043e\u0440\u0430\u0437\u043e\u0432\u0430\u044f \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u0430\u044f \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 train-\u043f\u0443\u043b\u0430; \u0440\u0430\u0437\u043c\u0435\u0440 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u043a\u0430\u043a **\u043f\u0440\u0435\u0444\u0438\u043a\u0441 \u044d\u0442\u043e\u0439 \u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438**, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 \u0441\u0442\u0440\u043e\u0433\u043e \u0432\u043b\u043e\u0436\u0435\u043d\u044b (n\u2081 \u2282 n\u2082 \u2282 \u2026). \u0421\u0435\u0442\u043a\u0430 \u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432 (\u0430\u0434\u0430\u043f\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u0434 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 N; \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440): {250, 500, 1000, 2000, 4000, 8000, 12000, N_train}. \u041f\u043e\u0432\u0442\u043e\u0440\u044b: R = 5\u201310 seeds (\u0444\u0438\u043d\u0430\u043b\u0438\u0437\u0438\u0440\u0443\u0435\u043c \u043f\u043e \u0431\u044e\u0434\u0436\u0435\u0442\u0443). \u0413\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u043a\u0430\u0436\u0434\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u044b \u043f\u043e\u0434\u0431\u0438\u0440\u0430\u044e\u0442\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 (\u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0439 5-fold CV \u043d\u0430 \u0441\u0440\u0435\u0434\u043d\u0435\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 2000) \u0438 **\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u0442\u043e\u0447\u0435\u043a \u043a\u0440\u0438\u0432\u043e\u0439**, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0442\u044c \u044d\u0444\u0444\u0435\u043a\u0442 \u0440\u0430\u0437\u043c\u0435\u0440\u0430 \u0441 \u043f\u0435\u0440\u0435\u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u043e\u0439 (\u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u0443 \u00abtune-per-size\u00bb \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043a \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437).\n\n**\u041c\u0435\u0442\u0440\u0438\u043a\u0438.** \u041d\u0430 \u0437\u0430\u043c\u043e\u0440\u043e\u0436\u0435\u043d\u043d\u043e\u043c \u0442\u0435\u0441\u0442\u0435: MAE (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f; \u0440\u0435\u043f\u043e\u0440\u0442\u043d\u043e \u0432 \u00abcounts\u00bb: MAE\u00d710\u2074) \u0438 R\u00b2; \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e RMSE \u0438 \u043d\u043e\u0440\u043c\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u0430\u044f \u043e\u0448\u0438\u0431\u043a\u0430 (MAE/\u03c3_test(Cd) \u0438 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u00ab\u043a\u043e\u043d\u0441\u0442\u0430\u043d\u0442\u043d\u043e\u0439\u00bb \u043c\u043e\u0434\u0435\u043b\u0438 \u043d\u0430 \u0441\u0440\u0435\u0434\u043d\u0435\u043c). \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u0430\u0440\u044b (\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430, \u0440\u0430\u0437\u043c\u0435\u0440) \u2014 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043f\u043e seed \u00b1 bootstrap-DI.\n\n**\u0421\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043d\u0430\u043a\u043b\u043e\u043d\u043e\u0432 \u043a\u0440\u0438\u0432\u044b\u0445.** (\u0430) \u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438: \u0444\u0438\u0442 \u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u0430 \u043e\u0431\u0443\u0447\u0435\u043d\u0438\u044f L(n)=a+b\u00b7n^(\u2212c) \u043f\u043e \u043a\u0430\u0436\u0434\u043e\u0439 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0435/seed; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u0435\u0439 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 c \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u043c\u0438 (bootstrap \u043f\u043e seeds). (b) \u041d\u0435\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0438: \u043f\u043e\u043f\u0430\u0440\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440 \u043f\u043e seeds \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u2014 Wilcoxon signed-rank \u0441 \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u043e\u0439 Holm (\u0438\u043b\u0438 Friedman+Nemenyi \u043f\u043e \u043c\u0430\u0442\u0440\u0438\u0446\u0435 \u00ab\u0440\u0430\u0437\u043c\u0435\u0440\u00d7\u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u00bb); (c) \u0441\u0432\u043e\u0434\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u00ab\u0440\u0430\u0437\u043c\u0435\u0440 \u00d7 \u0430\u0440\u0445\u0438\u0442\u0435\u043a\u0442\u0443\u0440\u0430\u00bb: \u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0430 log(n) \u0441\u043e \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u043c \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u043c seed (\u043f\u0440\u0438 R\u22656) \u2014 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043d\u0430 \u0432\u043e\u043f\u0440\u043e\u0441 \u00ab\u0440\u0430\u0437\u043b\u0438\u0447\u0430\u0435\u0442\u0441\u044f \u043b\u0438 \u0441\u0430\u043c \u043d\u0430\u043a\u043b\u043e\u043d\u00bb, \u0430 \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0443\u0440\u043e\u0432\u0435\u043d\u044c.\n\n**\u0411\u044e\u0434\u0436\u0435\u0442.** \u0422\u0430\u0431\u043b\u0438\u0447\u043d\u044b\u0435 \u043c\u0435\u0442\u043e\u0434\u044b (ridge/\u043f\u043e\u043b\u0438\u043d\u043e\u043c/GBT/RF/MLP): \u043c\u0438\u043d\u0443\u0442\u044b-CPU; \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u0435\u0442 GP. \u041f\u0440\u0438 8 \u0440\u0430\u0437\u043c\u0435\u0440\u0430\u0445 \u00d7 8 seeds \u00d7 (\u0441\u0435\u0442\u043a\u0430 \u043f\u043e\u0438\u0441\u043a\u0430 \u043e\u0434\u0438\u043d \u0440\u0430\u0437) \u043e\u0431\u0449\u0438\u0439 wall-time \u043e\u0446\u0435\u043d\u043e\u0447\u043d\u043e < 1\u20132 \u0447 \u043d\u0430 224 \u044f\u0434\u0440\u0430\u0445 \u2014 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442\u0441\u044f \u043f\u0438\u043b\u043e\u0442\u043e\u043c \u043f\u0435\u0440\u0435\u0434 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u043c \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u043c.\n\n## 3) \u041f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u0438, \u0442\u0440\u0435\u0431\u0443\u044e\u0449\u0438\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u044f\n\n1. **\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438 \u00ab\u0448\u0443\u043c\u00bb \u0446\u0435\u043b\u0438**: Cd \u0438\u0437 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0441\u0445\u043e\u0434\u0438\u0432\u0448\u0435\u0439\u0441\u044f RANS-\u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0438 \u2192 \u0441\u0447\u0438\u0442\u0430\u0435\u043c \u043c\u0435\u0442\u043a\u0438 \u0431\u0435\u0437 \u0448\u0443\u043c\u0430; \u0447\u0438\u0441\u043b\u0435\u043d\u043d\u0430\u044f \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c CFD \u043d\u0435 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f. \u041d\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u0442\u044c.\n2. **\u041e\u0431\u044a\u0451\u043c \u0434\u0430\u043d\u043d\u044b\u0445**: \u26a0 ~5000/\u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e, ~15 000 \u0432\u0441\u0435\u0433\u043e \u2014 \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b; \u043c\u0430\u043a\u0441\u0438\u043c\u0443\u043c learning curve \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e \u0444\u0430\u043a\u0442\u0443 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u0444\u0430\u0439\u043b\u0430. \u0415\u0441\u043b\u0438 \u0444\u0430\u0439\u043b\u043e\u0432 \u043d\u0435\u0442 \u0441\u043e\u0432\u0441\u0435\u043c (\u0442\u0435\u043a\u0443\u0449\u0438\u0439 \u0444\u0430\u043a\u0442) \u2014 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0434\u0438\u0437\u0430\u0439\u043d\u043e\u043c.\n3. **\u0423\u0442\u0435\u0447\u043a\u0430 \u043f\u0440\u0438 \u0440\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u0438**: \u043f\u0440\u0438 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u043c \u0440\u0430\u0437\u0431\u0438\u0435\u043d\u0438\u0438 \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0441\u0447\u0438\u0442\u0430\u0435\u043c \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0439, \u043d\u043e \u043f\u0435\u0440\u0435\u0434 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u043c \u043f\u043e\u0447\u0442\u0438-\u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u044b (\u043c\u0438\u043d. \u043f\u043e\u043f\u0430\u0440\u043d\u044b\u0435 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u043f\u043e 26 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0430\u043c); \u043f\u0440\u0438 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u043e\u0432 \u2014 grouped split \u043f\u043e \u043f\u043e\u0440\u043e\u0433\u043e\u0432\u043e\u0439 \u0431\u043b\u0438\u0437\u043e\u0441\u0442\u0438. \u0421\u0442\u0430\u0442\u0443\u0441: \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435, \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438.\n4. **\u041e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u0438\u0435 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432 \u043a\u0443\u0437\u043e\u0432\u043e\u0432**: \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u043e\u043d \u2014 pooled-\u0434\u0430\u043d\u043d\u044b\u0435 + \u043f\u0440\u0438\u0437\u043d\u0430\u043a \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430; \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u2014 \u043e\u0431\u0443\u0447\u0430\u0435\u043c \u043b\u0438 \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0435 \u0438 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u043c \u043b\u0438 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0435 (\u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u043c, \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0440\u0430\u0437\u0434\u0443\u0432\u0430\u0442\u044c \u0431\u044e\u0434\u0436\u0435\u0442). \u0421\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u0442\u044c.\n5. **\u0421\u0435\u043c\u0430\u043dantics 26 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u043e\u0432**: \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u0430\u0433\u0430\u0435\u043c \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u043e\u0432\u044b\u0435 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438 \u0431\u0435\u0437 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0430\u043b\u044c\u043d\u044b\u0445 \u043a\u043e\u043b\u043e\u043d\u043e\u043a \u0438 \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043e\u0432 (\u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044e \u0440\u0435\u043b\u0438\u0437\u0430); \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043d\u0430 \u0432\u0445\u043e\u0434\u0435.\n6. **\u0412\u044b\u0431\u0440\u043e\u0441\u044b**: Cd \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u043e \u0443\u043d\u0438\u043c\u043e\u0434\u0430\u043b\u0435\u043d (\u043f\u043e\u0440\u044f\u0434\u043e\u043a 0.19\u20130.36 \u26a0); \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u2014 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u0443\u0434\u0430\u043b\u044f\u0442\u044c, MAE \u043a\u0430\u043a \u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u0443\u0436\u0435 \u0440\u043e\u0431\u0430\u0441\u0442\u043d\u0430; \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u043e\u0442\u0441\u0435\u0447\u0435\u043d\u0438\u044f (>5 MAD \u0438 \u0442.\u043f.) \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0438 \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u0442\u0441\u044f \u043a train \u0431\u0435\u0437 \u0442\u0440\u043e\u0433\u0430\u043d\u0438\u044f \u0442\u0435\u0441\u0442\u0430.\n7. **\u0411\u044e\u0434\u0436\u0435\u0442 \u0438 software**: \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430, \u043f\u0430\u043a\u0435\u0442\u044b \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b. \u041d\u0443\u0436\u043d\u044b \u043b\u0438\u0431\u043e \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0435 wheels (numpy, pandas, scikit-learn, [lightgbm], \u043e\u043f\u0446. torch/GPy), \u043b\u0438\u0431\u043e \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u043d\u0430 numpy-\u0437\u0430\u043c\u0435\u043d\u0438\u0442\u0435\u043b\u044f\u0445. \u042d\u0442\u043e \u0431\u043b\u043e\u043a\u0435\u0440 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f, \u043d\u0435 \u0434\u0438\u0437\u0430\u0439\u043d\u0430. \u0427\u0438\u0441\u043b\u043e seeds \u0438 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0430\u043f\u0430\u0437\u043e\u043d n \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u043f\u043e\u0441\u043b\u0435 \u043e\u0446\u0435\u043d\u043a\u0438 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 GP.\n8. **\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u0433\u0438\u043f\u0435\u0440\u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432** (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 vs per-size) \u2014 \u043a\u043e\u043d\u0432\u0435\u043d\u0446\u0438\u044f, \u0432\u043b\u0438\u044f\u044e\u0449\u0430\u044f \u043d\u0430 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044e \u043d\u0430\u043a\u043b\u043e\u043d\u043e\u0432; \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u043c \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 (\u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437), \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u043c \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u0443.\n\n\u0413\u043e\u0442\u043e\u0432 \u0440\u0430\u0437\u0432\u0451\u0440\u043d\u0443\u0442\u044c \u043f\u043e\u043b\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d (\u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0441\u0435\u0442\u043e\u043a, \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b GP, \u043f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430) \u043f\u043e\u0441\u043b\u0435 \u0412\u0430\u0448\u0435\u0433\u043e \u043e\u0434\u043e\u0431\u0440\u0435\u043d\u0438\u044f \u044d\u0442\u043e\u0433\u043e \u043f\u043b\u0430\u043d\u0430.", "evidence": "\u0424\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438: (1) `ls -la /workspace` \u0438 `find /workspace` \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0444\u0430\u0439\u043b task.json (752 \u0411); \u0444\u0430\u0439\u043b\u043e\u0432 DrivAerNet++ (CSV \u0441 26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u043c\u0438, Cd, mesh/h5) \u043d\u0435\u0442; (2) `find / -maxdepth 4 -iname \"*drivaer*\"` \u2014 \u043f\u0443\u0441\u0442\u043e; (3) python3 3.14.4, \u0438\u043c\u043f\u043e\u0440\u0442 numpy/pandas/scipy/sklearn/torch/xgboost/lightgbm/matplotlib/h5py \u2014 \u0432\u0441\u0435 MISSING; \u0441\u0435\u0442\u044c \u043f\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044e \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430; GPU \u043d\u0435\u0442, 224 CPU-\u044f\u0434\u0440\u0430; (4) \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435 task.json \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442: design-only \u0437\u0430\u0434\u0430\u0447\u0430 (\u00abrepositories and compute are not required\u00bb), \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u044b \u043d\u0435 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u044b (datasets: []). \u0423\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043e DrivAerNet++ (3 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430 \u043a\u0443\u0437\u043e\u0432\u043e\u0432, ~5000 CFD \u043d\u0430 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e, 26 \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u044b\u0445 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432, Cd \u0438\u0437 RANS-CFD, CSV-\u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0432 \u0440\u0435\u043b\u0438\u0437\u0435) \u0432\u0437\u044f\u0442\u044b \u0438\u0437 \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u044f\u6570\u636e\u96c6 (Ahmed et al., DrivAerNet++ family) \u0438 \u0432 \u0434\u0430\u043d\u043d\u043e\u043c \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438 \u041d\u0415 \u0432\u0435\u0440\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u044b \u2014 \u044f\u0432\u043d\u043e \u043f\u043e\u043c\u0435\u0447\u0435\u043d\u044b \u043a\u0430\u043a \u043d\u0435\u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u043d\u044b\u0435 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f.", "assumptions": ["\u0424\u0430\u0439\u043b\u044b \u0434\u0430\u0442\u0430\u0441\u0435\u0442\u0430 DrivAerNet++ \u0431\u0443\u0434\u0443\u0442 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u044b \u043f\u043e\u0437\u0436\u0435 \u043b\u0438\u0431\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0447\u0438\u0441\u0442\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u043d\u044b\u043c; \u0442\u0435\u043a\u0443\u0449\u0438\u0435 \u0432\u044b\u0432\u043e\u0434\u044b \u043e\u043f\u0438\u0440\u0430\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0435 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435, \u0430 \u043d\u0435 \u043d\u0430 \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044e \u0434\u0430\u043d\u043d\u044b\u0445", "\u0426\u0435\u043b\u0435\u0432\u0430\u044f \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0430 \u2014 \u0441\u043a\u0430\u043b\u044f\u0440 Cd \u0438\u0437 \u0434\u0435\u0442\u0435\u0440\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 RANS-CFD, \u043c\u0435\u0442\u043a\u0438 \u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u043c\u0438 \u043e\u0442 \u0448\u0443\u043c\u0430", "\u041e\u0431\u044a\u0451\u043c \u0434\u0430\u043d\u043d\u044b\u0445 ~15 000 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u0439 (~5000 \u043d\u0430 fastback/notchback/estateback) \u2014 \u0438\u0437 \u043b\u0438\u0442\u0435\u0440\u0430\u0442\u0443\u0440\u044b, \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043e \u0444\u0430\u043a\u0442\u0443", "26 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u2014 \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u044b\u0435 \u0447\u0438\u0441\u043b\u043e\u0432\u044b\u0435 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438, \u043f\u0440\u043e\u043f\u0443\u0441\u043a\u043e\u0432 \u0438 \u0442\u043e\u0447\u043d\u044b\u0445 \u0434\u0443\u0431\u043b\u0438\u043a\u0430\u0442\u043e\u0432 \u043d\u0435\u0442 (\u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u0432\u0445\u043e\u0434\u0435 \u043f\u0435\u0440\u0435